import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import ListItem from './ListItem';

describe('ListItem', () => {
  test('should render without crash', () => {
    render(<ListItem variant="base">Text test</ListItem>);
    expect(screen.getByText('Text test')).toBeInTheDocument();
  });

  test('should render without crash in navigation variant', () => {
    render(<ListItem variant="navigation">Text test</ListItem>);
    expect(screen.getByText('Text test')).toBeInTheDocument();
  });

  test('should render without content', () => {
    render(<ListItem />);
    const el = document.querySelector('li');

    expect(el).toBeInTheDocument();
  });

  test('should not be clickable when disabled', () => {
    const mockFunction = jest.fn();

    render(<ListItem disabled>Test text</ListItem>);

    fireEvent.click(screen.getByText('Test text'));
    expect(mockFunction).not.toBeCalled();
  });

  test('should call onClick function when clicked', () => {
    const mockOnClick = jest.fn();

    render(
      <ListItem variant="navigation" onClick={mockOnClick}>
        Text test
      </ListItem>
    );

    fireEvent.click(screen.getByText('Text test'));

    expect(mockOnClick).toHaveBeenCalled();
  });

  test('should not call onClick function when clicked and its disabled', () => {
    const mockOnClick = jest.fn();

    render(
      <ListItem variant="navigation" onClick={mockOnClick} disabled>
        Text test
      </ListItem>
    );

    fireEvent.click(screen.getByText('Text test'));

    expect(mockOnClick).not.toHaveBeenCalled();
  });

  test('should render with medium spacing without crashing', () => {
    render(<ListItem spacing="medium">Text test</ListItem>);

    expect(screen.getByText('Text test')).toBeInTheDocument();
  });

  test('should render with large spacing without crashing', () => {
    render(<ListItem spacing="large">Text test</ListItem>);

    expect(screen.getByText('Text test')).toBeInTheDocument();
  });

  test('should render selected without crashing', () => {
    render(<ListItem>Text test</ListItem>);

    expect(screen.getByText('Text test')).toBeInTheDocument();
  });

  test('should render with divider', () => {
    render(<ListItem divider>Text test</ListItem>);

    expect(screen.getByText('Text test')).toBeInTheDocument();
  });

  test('should render with as prop', () => {
    render(<ListItem as="button">Text test</ListItem>);

    const buttonEl = document.querySelector('button');

    expect(buttonEl).toBeInTheDocument();
  });
});
